            polymorphs = json.load(f)
            composition = file.replace('_polymorphs.json', '')
            for p in polymorphs:
                p['source_composition'] = composition
            filtered_data.extend(polymorphs)
    except Exception as e:
        print(f"Error with {file}: {e}")
